#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_sh_exec_bits.sh: builds throwaway repositories
# with scripts committed at each mode and asserts the gate's exit code,
# in both the tree and the staged audit. The +x case is staged with
# `git update-index --chmod=+x` — the exact command the gate tells a
# developer to run — so the outcome does not depend on the test machine's
# core.filemode or the filesystem's exec support.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GATE="$ROOT/tests/check_sh_exec_bits.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

SANDBOX="$(mktemp -d)"
trap 'rm -rf "$SANDBOX"' EXIT
[ -n "$SANDBOX" ] && [ -d "$SANDBOX" ] || { echo "self-test: no sandbox" >&2; exit 2; }
SANDBOX="$(cd "$SANDBOX" && pwd)"

failures=0
check() { # name want-cmd got-cmd
    if [ "$2" = "$3" ]; then
        echo "ok    $1"
    else
        echo "FAIL  $1: want exit $2, got $3" >&2
        failures=$((failures + 1))
    fi
}

new_repo() { # name — git init + identity + seed commit, echoes the path
    dir="$SANDBOX/$1"
    mkdir -p "$dir" || return 1
    (
        cd "$dir" || exit 1
        git init -q . || exit 1
        git config user.email selftest@example.invalid || exit 1
        git config user.name Self-test || exit 1
        echo seed > seed.txt && git add seed.txt && git commit -qm seed || exit 1
    ) || return 1
    printf '%s' "$dir"
}

run_gate() { # dir [mode]
    ( cd "$1" && bash "$GATE" "${2:-tree}" ) >/dev/null 2>&1
    printf '%s' "$?"
}

# 1. Repo without any shell script: nothing to audit.
d=$(new_repo clean) || { echo "self-test: sandbox init failed" >&2; exit 2; }
check "tree: repo without scripts" 0 "$(run_gate "$d")"

# 2. Script committed with the exec bit.
(
    cd "$d" || exit 1
    printf '#!/usr/bin/env bash\ntrue\n' > good.sh
    git add good.sh && git update-index --chmod=+x good.sh && git commit -qm good
) >/dev/null 2>&1
check "tree: 100755 script" 0 "$(run_gate "$d")"

# 3. Script committed without it — the exit-126 landmine.
(
    cd "$d" || exit 1
    printf '#!/usr/bin/env bash\ntrue\n' > bad.sh
    git add bad.sh && git commit -qm bad
) >/dev/null 2>&1
check "tree: 100644 script" 1 "$(run_gate "$d")"

# 4. The 100644 commit alone, in a fresh repo, is still caught.
d2=$(new_repo solo-bad) || { echo "self-test: sandbox init failed" >&2; exit 2; }
(
    cd "$d2" || exit 1
    printf '#!/usr/bin/env bash\ntrue\n' > only.sh
    git add only.sh && git commit -qm only
) >/dev/null 2>&1
check "tree: sole 100644 script" 1 "$(run_gate "$d2")"

# 5. staged: a 100644 script in the index fails before the commit exists.
(
    cd "$d2" || exit 1
    rm only.sh
    printf '#!/usr/bin/env bash\ntrue\n' > staged-bad.sh
    git add staged-bad.sh
) >/dev/null 2>&1
check "staged: 100644 addition" 1 "$(run_gate "$d2" staged)"

# 6. staged: the gate's own remedy makes the same addition pass.
(
    cd "$d2" || exit 1
    git reset -q
    printf '#!/usr/bin/env bash\ntrue\n' > staged-good.sh
    git add staged-good.sh && git update-index --chmod=+x staged-good.sh
) >/dev/null 2>&1
check "staged: --chmod=+x addition" 0 "$(run_gate "$d2" staged)"

# 7. staged: a commit that stages no script passes regardless of the tree.
(
    cd "$d2" || exit 1
    git reset -q
    rm -f only.sh staged-bad.sh staged-good.sh
    echo more >> seed.txt && git add seed.txt
) >/dev/null 2>&1
check "staged: no script staged" 0 "$(run_gate "$d2" staged)"

# 8. Not a repository: not applicable.
mkdir -p "$SANDBOX/plain"
( cd "$SANDBOX/plain" && bash "$GATE" tree ) >/dev/null 2>&1
check "tree: outside a repo" 125 "$?"

if [ "$failures" -ne 0 ]; then
    echo "FAIL: $failures self-test case(s) mismatched" >&2
    exit 1
fi
echo "Self-test passed"
